// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type SportOverlayProps = Record<string, any>;

const SportOverlay: React.FC<SportOverlayProps> = ({
  backgroundColor = "#0f151e",
  transparentBackground = false,
  durationInSeconds = 57,
  accentColor = "#2b95ff",
  compassBgColor = "#1e2430",
  textColorPrimary = "#ffffff",
  textColorSecondary = "#e2e8f0",
  
  timeMinutes = 57,
  timeSeconds = 0,
  distanceKm = 10.0,
  paceMinutes = 5,
  paceSeconds = 42,
  heartRate = 165,
  cadence = 180,
  compassDegree = 339,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Timing ---
  const introDuration = 30;
  
  const containerOpacity = interpolate(frame, [0, introDuration], [0, 1], {
    extrapolateRight: "clamp",
  });
  const containerScale = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 },
    durationInFrames: introDuration,
  });

  // Main single-loop progress throughout the entire duration
  const progress = interpolate(frame, [introDuration, durationInFrames - 5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: (t) => t, // Linear progression for a steady run completion
  });

  // Fluctuations: generate pseudo-random organic ripples using math sine waves
  const fluctuationA = Math.sin(frame * 0.05) * 0.02;
  const fluctuationB = Math.cos(frame * 0.12) * 0.01;
  const rawProgressWithFluctuation = progress + fluctuationA + fluctuationB;
  const activeProgress = Math.max(0, Math.min(1, rawProgressWithFluctuation));

  // --- Data Interpolation with Fluctuation ---
  const currentTotalTimeSec = Math.floor(progress * (timeMinutes * 60 + timeSeconds));
  const currentMin = Math.floor(currentTotalTimeSec / 60);
  const currentSec = currentTotalTimeSec % 60;
  
  const currentDist = progress * distanceKm;
  
  // Pace, heart rate, and cadence fluctuate around dynamic target zones
  const currentHR = Math.floor(
    heartRate + Math.sin(frame * 0.04) * 8 + Math.cos(frame * 0.09) * 4
  );
  const currentCadence = Math.floor(
    cadence + Math.cos(frame * 0.05) * 6 + Math.sin(frame * 0.1) * 3
  );

  const totalPaceSec = paceMinutes * 60 + paceSeconds;
  // Fluctuating pace offset (seconds/km)
  const paceOffsetSec = Math.sin(frame * 0.03) * 15 + Math.cos(frame * 0.07) * 8;
  const currentPaceTotalSec = Math.max(1, Math.floor(totalPaceSec + paceOffsetSec));
  const currPaceMin = Math.floor(currentPaceTotalSec / 60);
  const currPaceSec = currentPaceTotalSec % 60;
  
  const currentDegree = Math.floor(progress * compassDegree);

  // --- Track Geometry Math ---
  const tw = 140 * s; // Track width
  const th = 300 * s; // Track height
  const tr = tw / 2;
  const sl = th - tw; // Straight length
  const cl = Math.PI * tr; // Curve length
  const tl = 2 * sl + 2 * cl; // Total path length

  const trackD = `
    M ${-tr} ${-sl / 2}
    L ${-tr} ${sl / 2}
    A ${tr} ${tr} 0 0 0 ${tr} ${sl / 2}
    L ${tr} ${-sl / 2}
    A ${tr} ${tr} 0 0 0 ${-tr} ${-sl / 2}
  `;

  // Exactly one complete loop around the track over the whole duration
  const dotProgress = progress;

  const getDotPos = (p: number) => {
    let d = (p % 1) * tl;
    if (d < 0) d += tl;
    
    // Left straight (going down)
    if (d <= sl) {
      return { x: -tr, y: -sl / 2 + d };
    }
    d -= sl;
    // Bottom curve (counter-clockwise in normal coords, so PI to 0)
    if (d <= cl) {
      const a = Math.PI - (d / cl) * Math.PI;
      return { x: tr * Math.cos(a), y: sl / 2 + tr * Math.sin(a) };
    }
    d -= cl;
    // Right straight (going up)
    if (d <= sl) {
      return { x: tr, y: sl / 2 - d };
    }
    d -= sl;
    // Top curve (0 to -PI)
    const a = 0 - (d / cl) * Math.PI;
    return { x: tr * Math.cos(a), y: -sl / 2 + tr * Math.sin(a) };
  };

  const dotPos = getDotPos(dotProgress);

  // --- Helper Components ---
  const StatBlock = ({ 
    label, 
    value, 
    unit = "", 
    showChart = false, 
    chartFillProgress = 0,
    index = 0
  }: { 
    label: string, 
    value: string, 
    unit?: string, 
    showChart?: boolean,
    chartFillProgress?: number,
    index?: number
  }) => {
    // Stagger opacity based on index
    const startF = index * 5;
    const blockOpacity = interpolate(frame, [startF, startF + 15], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
    const blockY = interpolate(frame, [startF, startF + 15], [20 * s, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

    return (
      <div style={{ 
        display: "flex", 
        flexDirection: "column", 
        gap: 8 * s,
        opacity: blockOpacity,
        transform: `translateY(${blockY}px)`,
        transition: "none",
        width: 320 * s
      }}>
        <div style={{ fontSize: 32 * s, color: textColorSecondary, fontWeight: 500 }}>
          {label}
        </div>
        <div style={{ display: "flex", alignItems: "baseline" }}>
          <div style={{ 
            fontSize: 76 * s, 
            color: textColorPrimary, 
            fontWeight: 800, 
            letterSpacing: "-0.02em",
            fontVariantNumeric: "tabular-nums" 
          }}>
            {value}
          </div>
          {unit && (
            <div style={{ 
              fontSize: 28 * s, 
              color: accentColor, 
              fontWeight: 800, 
              marginLeft: 12 * s,
              textTransform: "uppercase" 
            }}>
              {unit}
            </div>
          )}
        </div>
        {showChart && (
          <div style={{ display: "flex", gap: 6 * s, marginTop: 4 * s, height: 20 * s }}>
            {Array.from({ length: 18 }).map((_, i) => {
              const isFilled = i / 18 < chartFillProgress;
              const barOpacity = isFilled ? 1 : 0.2;
              return (
                <div key={i} style={{
                  width: 6 * s,
                  height: "100%",
                  backgroundColor: isFilled ? accentColor : textColorSecondary,
                  opacity: barOpacity,
                  borderRadius: 3 * s,
                  transition: "none"
                }} />
              );
            })}
          </div>
        )}
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, alignItems: "center", justifyContent: "center" }}>
      
      <div style={{
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "center",
        gap: 120 * s,
        opacity: containerOpacity,
        transform: `scale(${containerScale * 0.05 + 0.95})`,
        transition: "none",
        width: width * 0.9,
        height: height * 0.9,
      }}>
        
        {/* Left Side: Compass UI */}
        <div style={{
          position: "relative",
          width: 500 * s,
          height: 500 * s,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}>
          {/* Compass Background */}
          <div style={{
            position: "absolute",
            width: 460 * s,
            height: 460 * s,
            borderRadius: "50%",
            backgroundColor: compassBgColor,
            top: 0,
            left: "50%",
            transform: "translateX(-50%)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center"
          }}>
            {/* North Arrow */}
            <div style={{
              position: "absolute",
              top: -30 * s,
              width: 0,
              height: 0,
              borderLeft: `${16 * s}px solid transparent`,
              borderRight: `${16 * s}px solid transparent`,
              borderBottom: `${24 * s}px solid ${accentColor}`,
            }} />
            
            {/* 'N' Label */}
            <div style={{
              position: "absolute",
              top: 24 * s,
              color: textColorSecondary,
              fontSize: 32 * s,
              fontWeight: 700
            }}>
              N
            </div>

            {/* Track SVG */}
            <svg 
              width={300 * s} 
              height={400 * s} 
              viewBox={`${-150 * s} ${-200 * s} ${300 * s} ${400 * s}`}
              style={{ overflow: "visible", transform: `rotate(18deg)` }}
            >
              <path 
                d={trackD} 
                fill="none" 
                stroke="#ffffff" 
                strokeWidth={10 * s} 
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              {/* Rider Dot */}
              <circle 
                cx={dotPos.x} 
                cy={dotPos.y} 
                r={16 * s} 
                fill={accentColor} 
              />
            </svg>
          </div>

          {/* Bottom Degree Label */}
          <div style={{
            position: "absolute",
            bottom: -60 * s,
            fontSize: 48 * s,
            fontWeight: 800,
            color: textColorPrimary,
            fontVariantNumeric: "tabular-nums"
          }}>
            {currentDegree}°N
          </div>
        </div>

        {/* Right Side: Stats Grid */}
        <div style={{
          display: "flex",
          flexDirection: "column",
          gap: 60 * s,
        }}>
          {/* Row 1 */}
          <div style={{ display: "flex", gap: 80 * s }}>
            <StatBlock 
              index={1}
              label="Pace" 
              value={`${currPaceMin}'${currPaceSec.toString().padStart(2, '0')}"`} 
              unit="/KM" 
              showChart 
              chartFillProgress={activeProgress}
            />
            <StatBlock 
              index={2}
              label="Heart Rate" 
              value={currentHR.toString()} 
              unit="BPM" 
            />
          </div>

          {/* Row 2 */}
          <div style={{ display: "flex", gap: 80 * s }}>
            <StatBlock 
              index={3}
              label="Total Distance" 
              value={currentDist.toFixed(2)} 
              unit="KM" 
            />
            <StatBlock 
              index={4}
              label="Cadence" 
              value={currentCadence.toString()} 
              unit="SPM" 
              showChart 
              chartFillProgress={activeProgress}
            />
          </div>

          {/* Row 3 */}
          <div style={{ display: "flex", gap: 80 * s }}>
            <StatBlock 
              index={5}
              label="Time" 
              value={`${currentMin}:${currentSec.toString().padStart(2, '0')}`} 
            />
          </div>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default SportOverlay;